import unittest
from datetime import date

from flexdate import parse


class ParseTest(unittest.TestCase):
    def test_iso(self):
        self.assertEqual(parse('2026-11-05'), date(2026, 11, 5))

    def test_year_month(self):
        self.assertEqual(parse('2026-11'), date(2026, 11, 1))

    def test_dotted(self):
        self.assertEqual(parse('5.11.2026'), date(2026, 11, 5))

