import unittest

from flexdate import DateParseError, parse


class ErrorTest(unittest.TestCase):
    def assertParseError(self, text):
        with self.assertRaises(Exception) as cm:
            parse(text)
        self.assertIs(type(cm.exception), DateParseError)

    def test_impossible_date(self):
        self.assertParseError('2026-02-30')

    def test_ambiguous(self):
        self.assertParseError('2026-W45')

    def test_garbage(self):
        self.assertParseError('soon')
# API

parse(text) returns a datetime.date. It raises DateParseError, and nothing else, for any input it
cannot parse; callers catch that one exception. DateParseError subclasses ValueError.

